pub fn all_prefixes(s: Vec<char>) -> Vec<Vec<char>> {
    // Preallocate the result vector with the same capacity as the input length
    let mut result: Vec<Vec<char>> = Vec::with_capacity(s.len());

    // For each prefix length from 1 up to s.len(), clone the first i characters
    for i in 1..=s.len() {
        // s[0..i] is the slice of the first i elements
        result.push(s[0..i].to_vec());
    }

    result
}

